async function saveStockReceipt(e){
 e.preventDefault();if(busy)return;setBusy(true);setError('');
 const f=receiptForm;
 const isOpening=f.source==='opening_balance';
 const fn=isOpening?'hotel_record_opening_stock':'hotel_post_stock_purchase';
 const args=isOpening?
 {p_location:f.destination,p_product:f.product,p_quantity:Number(f.quantity),p_unit_cost:Number(f.unit_cost)}:
 {p_location:f.destination,p_product:f.product,p_quantity:Number(f.quantity),p_unit_cost:Number(f.unit_cost),p_source:f.source,p_supplier:f.supplier,p_reference:f.reference,p_request_key:stockEntryKey};
 const {error:err}=await supabase.rpc(fn,args);
 if(err)setError(err.message);else{
 setNotice(isOpening?'Opening stock initialized at selected location':'Stock purchased and added to assigned location.');
 setStockEntryKey(crypto.randomUUID());setReceiptForm(v=>({...v,quantity:'',unit_cost:'',reference:''}));
 await loadReceiptOptions();
 }
 setBusy(false);
}
