async function openStocktake(id){const{data,error:err}=await supabase.rpc('hotel_stocktake_detail',{p_id:id});if(err)setError(err.message);else{setStockDetail(data);setStockCounts({})}}
async function startStocktake(){setBusy(true);const{data,error:err}=await supabase.rpc('hotel_start_stocktake',{p_location:stockLocation});if(err)setError(err.message);else{await loadStocktaking();await openStocktake(data)}setBusy(false)}
async function saveStockCount(id){const value=stockCounts[id];if(value===undefined||value==='')return;const{error:err}=await supabase.rpc('hotel_stocktake_count',{p_line:id,p_quantity:Number(value)});if(err)setError(err.message);else if(stockDetail)setStockDetail(v=>({...v,lines:v.lines.map(x=>x.id===id?{...x,physical:Number(value)}:x)}))}
async function submitStocktake(){setBusy(true);const{error:err}=await supabase.rpc('hotel_stocktake_submit',{p_id:stockDetail.id});if(err)setError(err.message);else{await openStocktake(stockDetail.id);await loadStocktaking();setNotice('Stock count submitted for review')}setBusy(false)}
function stockMoved(x){return Math.max(0,Number(x.moved??Math.max(0,Number(x.total??x.system)-Number(x.system)))||0)}
function stockSalesAmount(x){return x.selling_price==null?'—':(stockMoved(x)*Number(x.selling_price)).toFixed(2)}
function printStockSheet(){if(!stockDetail){setError('Generate or open a stock sheet first.');return;}const headers=['No.','Item Name','Opening','Added','Total','Closing','Purchase Price/Unit','Selling Price','Moved Items','Amount (Sales)','Physical Count'];const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const rows=stockDetail.lines.length?stockDetail.lines.map((x,i)=>'<tr>'+[i+1,x.name+' ('+(x.unit||'unit')+')',x.opening??x.system,x.added??0,x.total??x.system,x.system,x.purchase_price??'—',x.selling_price??'—',stockMoved(x),stockSalesAmount(x),'________________'].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="11">No stock items registered for this location. Register stock items and opening balances before physical counting.</td></tr>';const html='<!doctype html><html><head><meta charset="utf-8"><title>MWISHO Stock Sheet</title><style>@page{size:A4 landscape;margin:9mm}body{font-family:Arial,sans-serif;color:#17263a;margin:0}h1{text-align:center;font-size:18px;margin:0 0 4px}h2{text-align:center;font-size:13px;margin:0 0 12px}.meta{display:flex;justify-content:space-between;margin:10px 0 15px;font-size:11px}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9px}th,td{border:1px solid #444;padding:6px 3px;overflow-wrap:anywhere}th{background:#e7eefb}th:nth-child(2){width:18%}th:nth-child(7),th:nth-child(8),th:nth-child(11){width:9%}tr{break-inside:avoid}.foot{display:flex;justify-content:space-between;margin-top:25px;font-size:11px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><h1>MWISHO MWISHO INVESTMENT</h1><h2>HOTEL STOCKTAKING SHEET — A4 LANDSCAPE</h2><div class="meta"><span>Location: '+esc(stockDetail.location)+'</span><span>Date: '+esc(new Date().toLocaleDateString('en-KE'))+'</span><span>Stock Taker: '+esc(access?.name||'')+'</span></div><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table><div class="foot"><span>Counted by: ___________________</span><span>Checked by: ___________________</span><span>Signature / Date: ___________________</span></div></body></html>';const w=window.open('','_blank');if(!w){setError('Allow pop-ups to print the stock sheet.');return;}w.document.open();w.document.write(html);w.document.close();w.onload=()=>w.print();}
function downloadStockVariance(){
 if(!stockDetail)return;
 const headers=['No.','Item Name','Opening','Added','Total','Closing','Purchase Price/Unit','Selling Price','Moved Items','Amount','Physical Count','Variance'];
 const rows=[headers,...stockDetail.lines.map((x,i)=>[
 i+1,x.name+' ('+(x.unit||'unit')+')',x.opening??x.system,x.added??0,x.total??x.system,x.system,
 x.purchase_price??'',x.selling_price??'',stockMoved(x),stockSalesAmount(x)==='—'?'':stockSalesAmount(x),
 x.physical??'',x.physical==null?'':Number(x.physical)-Number(x.system)
 ])];
 const csvCell=v=>{const value=String(v??'');return '"'+value.replaceAll('"','""')+'"';};
 const csv='sep=,\r\n'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n';
 const blob=new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'});
 const url=URL.createObjectURL(blob);const link=document.createElement('a');
 link.href=url;link.download='MWISHO-Stock-Sheet-'+stockDetail.id+'.csv';
 document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
}
async function exportStockSheet(format,includeVariance){
 if(!stockDetail){setError('Generate or open a stock sheet first.');return;}
 setError('');
 try{await downloadHotelStockSheet(stockDetail,{format,includeVariance});}
 catch(e){setError('Stock sheet download failed: '+(e?.message||String(e)));}
}
