async function submitRequisition(e){e.preventDefault();setBusy(true);setError('');const{error:err}=await supabase.rpc('submit_department_requisition',{p_department:reqDepartment,p_section:reqSection||null,p_purpose:reqPurpose,p_needed_on:null,p_items:reqItems});if(err)setError(err.message);else{setNotice('Requisition submitted');setReqPurpose('');setReqItems([{name:'',quantity:1,unit:'pcs'}]);await loadRequisitions()}setBusy(false)}
async function reviewRequisition(id,approve){setBusy(true);const{error:err}=await supabase.rpc('review_department_requisition',{p_id:id,p_approve:approve,p_note:null});if(err)setError(err.message);else await loadRequisitions();setBusy(false)}
async function loadSectionSales(){const {data,error:err}=await supabase.rpc('hotel_cashier_section_sales_report');if(err){setSalesReportError(err.message)}else{setSectionSales(data||[]);setSalesReportError('')}}async function loadDashboard(){setDashboardLoading(true);void loadStockConsumptionReport();void loadStockPurchasesReport();const{data,error:err}=await supabase.rpc('hotel_admin_dashboard');if(err)setError(err.message);else setDashboard(data);await loadSectionSales();setDashboardLoading(false)}
 async function signOut(){
 const rolesNow=access?.roles||[];
 const isWaiterNow=rolesNow.some(r=>r.department==='Hotel'&&['waiter','head_waiter','order_taker'].includes(r.role));
 const isCashierNow=rolesNow.some(r=>r.department==='Hotel'&&r.role==='cashier');
 if(isWaiterNow){
  const {data,error:err}=await supabase.rpc('hotel_my_waiter_shifts');
  if(err){setError(err.message);return}
  if((data||[]).some(x=>!x.closed_at)){setSection('My Shift');setWaiterShifts(data||[]);setNotice('End your active shift first. You can then choose to print your report.');return}
  const last=(data||[]).find(x=>x.closed_at);
  if(last&&!shiftReportOffer&&window.confirm('Would you like to view or print your completed waiter shift report before signing out?')){
   setShiftReportOffer(true);await viewShiftReport(last.id,'waiter');return;
  }
 }
 if(isCashierNow){
  const {data,error:err}=await supabase.rpc('hotel_my_cashier_shifts');
  if(err){setError(err.message);return}
  if((data||[]).some(x=>x.shift_id&&!x.closed_at)){setSection('Cashier Shifts');setShifts(data||[]);setNotice('Close your cashier shift first. You can then choose to print your report.');return}
  const last=(data||[]).find(x=>x.shift_id&&x.closed_at);
  if(last&&!shiftReportOffer&&window.confirm('Would you like to view or print your last cashier shift report before signing out?')){
   setShiftReportOffer(true);await viewShiftReport(last.shift_id,'cashier');return;
  }
 }
 setShiftReport(null);setShiftReportOffer(false);
 await supabase.auth.signOut();setAccess(null);
}

