function printStaffShiftReport(report){
 if(!report)return;
 const w=window.open('','_blank','width=880,height=960');
 if(!w){setError('Enable pop-ups to print your shift report.');return}
 const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
 const money=x=>'KSh '+Number(x||0).toLocaleString('en-KE',{minimumFractionDigits:2,maximumFractionDigits:2});
 const date=x=>x?new Date(x).toLocaleString('en-KE',{timeZone:'Africa/Nairobi',dateStyle:'medium',timeStyle:'short'}):'—';
 const details=(report.pending_bills||[]).map(b=>'<tr><td>#'+esc(b.order_number)+'</td><td>'+esc(b.table_label)+'</td><td>'+esc(b.counter||'')+'</td><td class="num">'+money(b.total)+'</td></tr>').join('');
 const cards=[['Gross sales',money(report.total_sales)],['Tables served',report.tables_served||0],['Orders',report.orders??report.orders_cleared??0],['Pending bills value',money(report.pending_amount)]];
 if(report.type==='waiter')cards.splice(1,0,['Paid sales',money(report.paid_sales)]);
 if(report.type==='cashier')cards.push(['Opening float',money(report.opening_float)],['Cash collections',money(report.cash_collected)],['M-Pesa collections',money(report.mpesa_collected)],['Expected cash',money(report.expected_cash)],['Closing cash',money(report.closing_cash)],['Cash variance',money(report.cash_variance)]);
 const box=cards.map(([k,v])=>'<div class="stat"><small>'+esc(k)+'</small><b>'+esc(v)+'</b></div>').join('');
 w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>MWISHO Shift Report</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#27243b;margin:0}header{border-bottom:3px solid #6b46c1;padding:0 0 16px;margin:0 0 18px}h1{font-size:23px;margin:0;color:#302255}h2{font-size:14px;margin:24px 0 10px}.muted{color:#656477;font-size:12px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:16px 0;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{border:1px solid #ddd8ee;border-radius:8px;padding:12px;break-inside:avoid}.stat small{display:block;font-size:10px;color:#6a6580}.stat b{display:block;font-size:15px;margin-top:5px}table{width:100%;border-collapse:collapse;font-size:11px}td,th{padding:9px;border-bottom:1px solid #e1dfe8;text-align:left}.num{text-align:right}footer{margin-top:32px;border-top:1px solid #ddd;padding-top:12px;font-size:10px;color:#777}@media print{.print{display:none}}</style></head><body><header><h1>MWISHO TOURIST HOTEL</h1><div class="muted">STAFF SHIFT REPORT · '+esc(report.type?.toUpperCase())+' · '+esc(report.status?.toUpperCase())+'</div></header><div class="meta"><div><b>Staff member:</b> '+esc(report.staff)+'</div><div><b>Work area:</b> '+esc(report.counter||(report.work_areas||[]).join(', ')||'Assigned Restaurant / Bar')+'</div><div><b>Shift started:</b> '+esc(date(report.start))+'</div><div><b>Shift ended:</b> '+esc(date(report.end))+'</div><div><b>Shift reference:</b> '+esc(report.shift_id)+'</div></div><div class="grid">'+box+'</div><h2>Outstanding orders / bills</h2><table><thead><tr><th>Order</th><th>Table / Guest</th><th>Work Area</th><th class="num">Unpaid</th></tr></thead><tbody>'+(details||'<tr><td colspan="4">No pending bills on this shift.</td></tr>')+'</tbody></table><footer>Generated by MWISHO POS · Kenya time (EAT) · This report does not cancel or settle pending customer bills.</footer><p class="print"><button onclick="window.print()">Print report</button></p></body></html>');
 w.document.close();w.focus();
}
const MENU_IMAGE_BUCKET='mwisho-hotel-menu';
const MENU_IMAGE_MAX_BYTES=3*1024*1024;
function groupHotelMenu(items){
 const groups=new Map();
 for(const item of items){
  const parts=String(item.name||'').split(/\s+[—–]\s+/);
  const base=(parts.length>1?parts.slice(0,-1).join(' — '):parts[0]).trim();
  const variant=(parts.length>1?parts[parts.length-1]:'').trim();
  const key=item.preparation_area+'::'+base.toLocaleLowerCase();
  if(!groups.has(key))groups.set(key,{key,name:base,preparation_area:item.preparation_area,variations:[],image_url:null});
  const group=groups.get(key);
  group.variations.push({...item,variant_label:variant||'Standard'});
  if(!group.image_url&&item.image_url)group.image_url=item.image_url;
 }
 return Array.from(groups.values()).map(group=>({...group,
  id:group.key,price:Math.min(...group.variations.map(v=>Number(v.price))),
  variationCount:group.variations.length}));
}
const fallbackMenuEmoji=p=>/chicken|wing|drumstick/i.test(p.name)?'🍗':/fish|tilapia/i.test(p.name)?'🐟':/beef|steak|nyama/i.test(p.name)?'🥩':/pizza/i.test(p.name)?'🍕':/burger/i.test(p.name)?'🍔':/chips|fries/i.test(p.name)?'🍟':/rice|pilau/i.test(p.name)?'🍚':/coffee/i.test(p.name)?'☕':/juice|soda|cola/i.test(p.name)?'🥤':/beer|lager/i.test(p.name)?'🍺':/whisky|jack|gin|vodka|wine|spirit|jameson/i.test(p.name)?'🥃':p.preparation_area==='bar'?'🍹':'🍲';
function MenuTilePhoto({item}){
 const [failed,setFailed]=React.useState(false);
 React.useEffect(()=>setFailed(false),[item.image_url]);
 return item.image_url&&!failed?<img src={item.image_url} alt={item.name} loading="lazy" onError={()=>setFailed(true)}/>:<span aria-hidden="true">{fallbackMenuEmoji(item)}</span>;
}
async function attachMenuImages(items){
 if(!items?.length)return items||[];
 const {data,error:photoError}=await supabase.rpc('hotel_menu_image_map');
 if(photoError){setError('Item photo lookup failed: '+photoError.message);return items;}
 const paths=new Map((data||[]).filter(x=>x.image_path).map(x=>[x.product_id,x.image_path]));
 return items.map(item=>({...item,image_path:paths.get(item.id)||null,image_url:paths.has(item.id)?supabase.storage.from(MENU_IMAGE_BUCKET).getPublicUrl(paths.get(item.id)).data.publicUrl:null}));
}
async function saveMenuPhoto(file,ids){
 if(!file)return;
 if(!Array.isArray(ids)||ids.length<1||ids.some(id=>!id))throw new Error('Item IDs were not returned. Photo cannot be linked.');
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPG, PNG or WebP photo');
 if(file.size>MENU_IMAGE_MAX_BYTES)throw new Error('Image must be under 3 MB');
 if(file.size===0)throw new Error('Selected photo is empty. Choose another image.');
 const ext=file.type==='image/jpeg'?'jpg':file.type==='image/png'?'png':'webp';
 const path='hotel/'+crypto.randomUUID()+'.'+ext;
 const {error:uploadError}=await supabase.storage.from(MENU_IMAGE_BUCKET).upload(path,file,{contentType:file.type,upsert:false,cacheControl:'3600'});
 if(uploadError)throw new Error('Image could not be saved in MWISHO Storage: '+uploadError.message);
 const {data:storedFiles,error:storedError}=await supabase.storage.from(MENU_IMAGE_BUCKET).list('hotel',{search:path.split('/')[1],limit:5});
 if(storedError||!storedFiles?.some(x=>x.name===path.split('/')[1]))throw new Error('The image upload has not been verified in MWISHO Storage. '+(storedError?.message||'Try again.'));
 const {error:linkError}=await supabase.rpc('hotel_set_menu_image',{p_products:ids,p_path:path});
 if(linkError)throw new Error('Photo reached Storage, but could not be linked to this menu item: '+linkError.message);
 const {data:verified,error:verificationError}=await supabase.rpc('hotel_menu_image_map');
 if(verificationError)throw new Error('Photo uploaded but verification failed: '+verificationError.message);
 if(!ids.every(id=>(verified||[]).some(x=>x.product_id===id&&x.image_path===path)))throw new Error('Photo uploaded but was not linked to every selected item. Please retry.');
 return supabase.storage.from(MENU_IMAGE_BUCKET).getPublicUrl(path).data.publicUrl;
}
async function attachExistingProductPhoto(productId,file){
 if(!file)return;
 setBusy(true);setError('');
 try{
  await saveMenuPhoto(file,[productId]);
  await loadManagementMenu();
  setNotice('Verified: photo saved in MWISHO Storage and linked to this item. Refresh the Staff POS menu to see it.');
 }catch(e){setError('Unable to attach item photo: '+e.message)}
 finally{setBusy(false)}
}
